import pytest

from click.testing import CliRunner


@pytest.fixture(scope="function")
def runner(request):
    return CliRunner()

"""A second Ctrl-C while ``Command.main()`` reported an abort or an error used
to escape as an unhandled traceback: the message and the exit both ran in
``except`` clauses, outside every ``try`` that caught ``KeyboardInterrupt``.
https://github.com/pallets/click/issues/3802

The fix holds one policy, the one the pager has followed since
https://github.com/pallets/click/pull/351: a late interrupt must not replace
the intended outcome. In standalone mode the collected exit code wins, for
aborts, errors and success alike, and the message is best effort. Without
standalone mode the interrupt propagates to the caller. Two settled contracts
stay in place: the first interrupt reaches a non-standalone caller as
``Abort`` (https://github.com/pallets/click/pull/2380), and the ``Aborted!``
message stays as it is (declined in
https://github.com/pallets/click/issues/1447 and
https://github.com/pallets/click/issues/2584).
"""

import sys

import pytest

import click


class RecordingStderr:
    """A stderr stand-in that records what is written to it.

    With ``interrupt_at=N``, the ``N``-th ``isatty()`` call raises
    ``KeyboardInterrupt``. ``echo()`` calls ``isatty()`` before writing, which
    is where the traceback in issue #3802 ended.
    """

    def __init__(self, interrupt_at=None):
        self.text = ""
        self.interrupt_at = interrupt_at
        self.isatty_calls = 0

    def isatty(self):
        self.isatty_calls += 1

        if self.isatty_calls == self.interrupt_at:
            raise KeyboardInterrupt

        return False

    def write(self, value):
        self.text += value
        return len(value)

    def flush(self):
        pass


def _interrupt_prompt(text):
    """Stand in for ``input()`` when the user presses Ctrl-C at a prompt."""
    raise KeyboardInterrupt


def _prompting_command():
    @click.command()
    @click.option("--name", prompt="Name")
    def cli(name):
        click.echo(name)

    return cli


def _interrupting_command():
    @click.command()
    def cli():
        raise KeyboardInterrupt

    return cli


def _exit_code(cli, stderr, monkeypatch):
    """Run *cli* in standalone mode and return its exit code."""
    monkeypatch.setattr(sys, "stderr", stderr)

    try:
        cli.main([], "cli")
    except SystemExit as e:
        return e.code
    except KeyboardInterrupt:
        pytest.fail("KeyboardInterrupt escaped Command.main()")

    pytest.fail("Command.main() returned without exiting")


@pytest.mark.parametrize(
    ("source", "interrupt_at"),
    [("prompt", None), ("prompt", 1), ("body", None), ("body", 1), ("body", 2)],
)
def test_interrupt_while_reporting_abort(monkeypatch, source, interrupt_at):
    """Exit code 1 survives a second Ctrl-C; the message may not.

    The counted ``isatty`` picks the window. A prompt converts the interrupt
    to ``Abort`` itself, so the only window left in ``Command.main()`` is the
    ``Aborted!`` message (``1``). An interrupt from the command body goes
    through the conversion in ``Command.main()``, which writes a blank line
    first (``1``), before the message (``2``).
    """
    if source == "prompt":
        monkeypatch.setattr("click.termui.visible_prompt_func", _interrupt_prompt)
        cli = _prompting_command()
    else:
        cli = _interrupting_command()

    stderr = RecordingStderr(interrupt_at=interrupt_at)

    assert _exit_code(cli, stderr, monkeypatch) == 1

    if interrupt_at is None:
        assert "Aborted!" in stderr.text


def test_interrupt_while_reporting_error(monkeypatch):
    """A Ctrl-C while Click writes an error keeps the error's exit code."""

    class InterruptedReport(click.ClickException):
        exit_code = 3

        def show(self, file=None):
            raise KeyboardInterrupt

    @click.command()
    def cli():
        raise InterruptedReport("boom")

    assert _exit_code(cli, RecordingStderr(), monkeypatch) == 3


def test_late_interrupt_with_disabled_standalone_mode(monkeypatch):
    """Without standalone mode, a late interrupt reaches the caller, not exit 1.

    The patched ``Abort`` raises a second ``KeyboardInterrupt`` from its
    constructor: it lands on the ``raise Abort() from e`` statement that
    ``Command.main()`` only runs for non-standalone callers.
    """

    class InterruptedAbort(click.Abort):
        def __init__(self):
            raise KeyboardInterrupt

    monkeypatch.setattr(click.core, "Abort", InterruptedAbort)
    cli = _interrupting_command()
    monkeypatch.setattr(sys, "stderr", RecordingStderr())

    with pytest.raises(KeyboardInterrupt):
        cli.main([], "cli", standalone_mode=False)


def test_interrupt_while_exiting_after_success(monkeypatch):
    """A Ctrl-C while a successful exit propagates keeps exit code 0.

    The uniform policy: the run completed before the interrupt arrived, so the
    intended outcome wins for success exactly as it does for aborts and
    errors.
    """

    @click.command()
    def cli():
        click.echo("done")

    real_exit = sys.exit
    codes = []

    def interrupted_exit(code=None):
        codes.append(code)

        if len(codes) == 1:
            raise KeyboardInterrupt

        real_exit(code)

    monkeypatch.setattr(sys, "exit", interrupted_exit)

    assert _exit_code(cli, RecordingStderr(), monkeypatch) == 0
    assert codes == [0, 0]

import itertools
import sys
import unicodedata
import warnings
from unittest import mock

import pytest
from test_options import ENV_NAMES_ARE_CASE_INSENSITIVE

import click
from click._utils import UNSET


def test_nargs_star(runner):
    @click.command()
    @click.argument("src", nargs=-1)
    @click.argument("dst")
    def copy(src, dst):
        click.echo(f"src={'|'.join(src)}")
        click.echo(f"dst={dst}")

    result = runner.invoke(copy, ["foo.txt", "bar.txt", "dir"])
    assert not result.exception
    assert result.output.splitlines() == ["src=foo.txt|bar.txt", "dst=dir"]


def test_nargs_tup(runner):
    @click.command()
    @click.argument("name", nargs=1)
    @click.argument("point", nargs=2, type=click.INT)
    def copy(name, point):
        click.echo(f"name={name}")
        x, y = point
        click.echo(f"point={x}/{y}")

    result = runner.invoke(copy, ["peter", "1", "2"])
    assert not result.exception
    assert result.output.splitlines() == ["name=peter", "point=1/2"]


@pytest.mark.parametrize(
    "opts",
    [
        dict(type=(str, int)),
        dict(type=click.Tuple([str, int])),
        dict(nargs=2, type=click.Tuple([str, int])),
        dict(nargs=2, type=(str, int)),
    ],
)
def test_nargs_tup_composite(runner, opts):
    @click.command()
    @click.argument("item", **opts)
    def copy(item):
        name, id = item
        click.echo(f"name={name} id={id:d}")

    result = runner.invoke(copy, ["peter", "1"])
    assert result.exception is None
    assert result.output.splitlines() == ["name=peter id=1"]


def test_nargs_mismatch_with_tuple_type():
    with pytest.raises(ValueError, match="nargs.*must be 2.*but it was 3"):

        @click.command()
        @click.argument("test", type=(str, int), nargs=3)
        def cli(_):
            pass


def test_nargs_err(runner):
    @click.command()
    @click.argument("x")
    def copy(x):
        click.echo(x)

    result = runner.invoke(copy, ["foo"])
    assert not result.exception
    assert result.output == "foo\n"

    result = runner.invoke(copy, ["foo", "bar"])
    assert result.exit_code == 2
    assert "Got unexpected extra argument (bar)" in result.output


@pytest.mark.parametrize(
    ("decl", "expect"),
    [
        ("src", "src"),
        ("foo-bar", "foo_bar"),
        ("FOO-BAR", "foo_bar"),
        ("Foo_Bar", "foo_bar"),
        ("foo__bar", "foo__bar"),
        ("_foo", "_foo"),
        ("__foo", "__foo"),
    ],
)
def test_argument_names(runner, decl, expect):
    @click.command()
    @click.argument(decl)
    def cmd(**kwargs):
        click.echo(kwargs[expect])

    assert cmd.params[0].name == expect

    result = runner.invoke(cmd, ["value"])
    assert not result.exception
    assert result.output == "value\n"


def test_argument_normalizes_an_identifier_decl():
    """An argument transforms its declaration; an option keeps an explicit name."""
    assert click.Argument(["Foo_Bar"]).name == "foo_bar"

    with pytest.warns(DeprecationWarning, match="lower cases an explicit name"):
        assert click.Option(["--x", "Foo_Bar"]).name == "Foo_Bar"


PARAM_KINDS = [
    pytest.param(click.Argument, "{decl}", id="argument"),
    pytest.param(click.Option, "--{decl}", id="option"),
]

# Declarations whose lower casing is neither one-to-one nor length-preserving.
UNICODE_CASE_DECLS = [
    pytest.param("Ω", "ω", id="omega"),
    pytest.param("İ", "i\N{COMBINING DOT ABOVE}", id="dotted-capital-i"),
    pytest.param("ΟΔΟΣ", "οδος", id="final-sigma"),
    pytest.param("ẞ", "ß", id="capital-sharp-s"),
    pytest.param("\N{KELVIN SIGN}", "k", id="kelvin-sign"),
    pytest.param("foo-٣", "foo_٣", id="arabic-indic-digit"),
]

NAME_TRANSFORM_DECLS = UNICODE_CASE_DECLS + [
    pytest.param("a-b-c", "a_b_c", id="interior-singles"),
    pytest.param("a-----b", "a_____b", id="interior-run"),
    pytest.param("a--", "a__", id="trailing"),
    pytest.param("-a-", "_a_", id="leading-survives-the-prefix"),
    pytest.param("-a----b--", "_a____b__", id="everywhere"),
    pytest.param("--", "__", id="dashes-only"),
    pytest.param("_-_", "___", id="around-an-underscore"),
]

# Declarations covering every shape the naming transform accepts.
NAME_SWEEP_DECLS = [
    "",
    "-",
    "--",
    "---",
    "0",
    "--0",
    "0-file",
    "--0-file",
    "foo.bar",
    "--foo.bar",
    "foo bar",
    "x",
    "--x",
    "X_Y",
    "--X-Y",
]


@pytest.mark.parametrize("count", [1, 2])
@pytest.mark.parametrize("expose_value", [True, False])
def test_parameter_name_is_an_identifier_or_deprecated(count, expose_value):
    built = 0

    for decls in itertools.product(NAME_SWEEP_DECLS, repeat=count):
        for cls in (click.Option, click.Argument):
            with warnings.catch_warnings(record=True) as caught:
                warnings.simplefilter("always")

                try:
                    param = cls(list(decls), expose_value=expose_value)
                except (TypeError, ValueError):
                    continue

            built += 1

            if param.name.isidentifier():
                continue

            assert any(issubclass(w.category, DeprecationWarning) for w in caught), (
                f"{cls.__name__}({list(decls)!r}, expose_value={expose_value})"
                f" named its parameter {param.name!r} without a warning"
            )

    assert built, "the sweep built no parameter, so it proves nothing"


def test_argument_requires_its_one_declaration():
    """An exposed argument with no declaration is refused, an unexposed one warns."""
    with pytest.raises(TypeError, match="does not have a name"):
        click.Argument([])

    with pytest.warns(DeprecationWarning, match="not a valid Python identifier"):
        assert click.Argument([], expose_value=False).name == ""


def test_argument_name_check_applies_when_not_exposed():
    """An unexposed argument keeps the name, and says Click 9.0 will refuse it."""
    with pytest.warns(DeprecationWarning, match="not a valid Python identifier"):
        assert click.Argument(["0foo"], expose_value=False).name == "0foo"


def test_argument_metavar_renders_what_a_declaration_may_not(runner):
    """``metavar`` carries a display the declaration is no longer allowed to.

    An argument takes exactly one declaration and has no explicit-name channel,
    so a display such as ``0FOO`` is reached by naming the parameter separately
    and passing the display as ``metavar``.
    """
    seen = []

    def record(ctx, param, value):
        seen.append(value)

    @click.command()
    @click.argument("zero_foo", expose_value=False, callback=record, metavar="0FOO")
    def cmd(**kwargs):
        click.echo(repr(kwargs))

    assert cmd.params[0].name == "zero_foo"

    result = runner.invoke(cmd, ["value"])
    assert not result.exception
    assert result.output == "{}\n"
    assert seen == ["value"]

    result = runner.invoke(cmd, ["--help"])
    assert "0FOO" in result.output


@pytest.mark.parametrize(("cls", "form"), PARAM_KINDS)
@pytest.mark.parametrize(("decl", "expect"), NAME_TRANSFORM_DECLS)
def test_parameter_name_transform(cls, form, decl, expect):
    """``str.lower()`` is neither one-to-one nor length-preserving, and a
    dash becomes an underscore everywhere except an option's prefix.
    """
    assert cls([form.format(decl=decl)]).name == expect


@pytest.mark.parametrize(("decl", "expect"), UNICODE_CASE_DECLS)
def test_option_explicit_name_keeps_its_case(decl, expect):
    """An explicit name is kept as spelled, where Click 9.0 transforms it."""
    if not decl.isidentifier():
        assert click.Option(["--x", decl]).name == "x"
        return

    with pytest.warns(DeprecationWarning, match="lower cases an explicit name"):
        assert click.Option(["--x", decl]).name == decl

    assert decl.lower() == expect


@pytest.mark.parametrize(("cls", "form"), PARAM_KINDS)
@pytest.mark.parametrize(
    "decl",
    [
        pytest.param("0foo", id="leading-digit"),
        pytest.param("0", id="digit-only"),
        pytest.param("foo.bar", id="dot"),
        pytest.param("foo bar", id="space"),
        pytest.param("\u0663foo", id="leading-arabic-indic-digit"),
        # Separators that read as a hyphen but are not the one replaced.
        pytest.param("foo\N{NON-BREAKING HYPHEN}bar", id="non-breaking-hyphen"),
        pytest.param("foo\u2013bar", id="en-dash"),
        pytest.param("foo\u2212bar", id="minus-sign"),
        # Characters that occupy no width at all.
        pytest.param("a\N{ZERO WIDTH SPACE}b", id="zero-width-space"),
        pytest.param("a\N{SOFT HYPHEN}b", id="soft-hyphen"),
        pytest.param("a\N{RIGHT-TO-LEFT OVERRIDE}b", id="right-to-left-override"),
        # Even nothing at all, which reaches an option as a bare ``--``.
        pytest.param("", id="empty"),
    ],
)
def test_parameter_name_not_an_identifier_is_deprecated(cls, form, decl):
    """Click 9.0 refuses every one of these; 8.6 keeps them and says so.

    An exposed option is the exception, since it already refuses them.
    """
    spec = form.format(decl=decl)

    if cls is click.Option:
        with pytest.raises(TypeError, match="Could not determine name"):
            cls([spec])
        return

    with pytest.warns(DeprecationWarning, match="not a valid Python identifier"):
        param = cls([spec])

    assert not param.name.isidentifier()


@pytest.mark.parametrize(("cls", "form"), PARAM_KINDS)
@pytest.mark.parametrize(
    "char",
    [
        pytest.param("\N{ZERO WIDTH JOINER}", id="zero-width-joiner"),
        pytest.param("\N{ZERO WIDTH NON-JOINER}", id="zero-width-non-joiner"),
    ],
)
def test_parameter_name_identifier_check_follows_the_unicode_table(cls, form, char):
    """Python 3.13 allows unicode zero-width joiner and non-joiner in identifiers."""
    name = f"a{char}b"
    assert name.isidentifier() == (sys.version_info >= (3, 13))
    decl = form.format(decl=name)

    if name.isidentifier():
        assert cls([decl]).name == name
        return

    if cls is click.Option:
        with pytest.raises(TypeError, match="Could not determine name"):
            cls([decl])
        return

    with pytest.warns(DeprecationWarning, match="not a valid Python identifier"):
        assert cls([decl]).name == name


@pytest.mark.parametrize(
    ("decorator", "decl", "argv"),
    [
        pytest.param(click.argument, "ﬁ", ["value"], id="argument"),
        pytest.param(click.option, "--ﬁ", ["--ﬁ", "value"], id="option"),
    ],
)
def test_parameter_name_is_not_nfkc_normalized(runner, decorator, decl, argv):
    """``str.isidentifier()`` is not the test for "can be a parameter name".

    Python normalizes an identifier written in source to NFKC, so the ligature
    "fi" compiles to the two letters. ``_parse_decls`` runs no normalization,
    so the name keeps the ligature and only ``**kwargs`` can carry it.
    """

    @click.command()
    @decorator(decl)
    def cmd(**kwargs):
        click.echo(repr(kwargs))

    name = cmd.params[0].name
    assert name == "ﬁ"
    assert name.isidentifier()
    assert unicodedata.normalize("NFKC", name) == "fi"

    result = runner.invoke(cmd, argv)
    assert not result.exception
    assert result.output == "{'ﬁ': 'value'}\n"


def test_argument_name_keeps_its_normalization_form(runner):
    """A composed and a decomposed declaration are two distinct arguments.

    Both render as ``café`` and both are valid identifiers, so the pair
    coexists on one command with nothing on screen to tell them apart.
    """
    decomposed = "cafe\N{COMBINING ACUTE ACCENT}"
    composed = unicodedata.normalize("NFC", decomposed)

    @click.command()
    @click.argument(composed)
    @click.argument(decomposed)
    def cmd(**kwargs):
        click.echo(repr(sorted(kwargs)))

    assert [p.name for p in cmd.params] == [composed, decomposed]

    result = runner.invoke(cmd, ["one", "two"])
    assert not result.exception
    assert result.output == f"['{decomposed}', '{composed}']\n"


def test_argument_name_case_transform_can_collide(runner):

    @click.command()
    @click.argument("Foo-Bar")
    @click.argument("foo_bar")
    def cmd(**kwargs):
        click.echo(repr(kwargs))

    with pytest.warns(UserWarning, match="is used by an argument"):
        result = runner.invoke(cmd, ["one", "two"], catch_exceptions=False)

    assert result.output == "{'foo_bar': 'two'}\n"


def test_argument_name_can_collide_with_an_option(runner):

    @click.command()
    @click.option("--foo-bar")
    @click.argument("Foo-Bar", required=False)
    def cmd(**kwargs):
        click.echo(repr(kwargs))

    assert [p.name for p in cmd.params] == ["foo_bar", "foo_bar"]

    with pytest.warns(UserWarning, match="is used by an argument"):
        result = runner.invoke(
            cmd, ["--foo-bar", "from-option", "from-argument"], catch_exceptions=False
        )

    assert result.output == "{'foo_bar': 'from-argument'}\n"


def test_argument_has_no_auto_envvar(runner):
    """An argument reads only the envvars it names, never a derived one."""

    @click.command()
    @click.argument("Foo-Bar", required=False)
    def cmd(**kwargs):
        click.echo(repr(kwargs))

    result = runner.invoke(
        cmd, [], auto_envvar_prefix="TEST", env={"TEST_FOO_BAR": "foo"}
    )
    assert not result.exception
    assert result.output == "{'foo_bar': None}\n"


@pytest.mark.parametrize(
    ("env", "expect"),
    [
        pytest.param({"ArG": "foo"}, "'foo'", id="exact"),
        pytest.param({"ARG": "foo"}, "None", id="upper"),
        pytest.param({"arg": "foo"}, "None", id="lower"),
    ],
)
def test_argument_explicit_envvar_case_sensitivity(runner, env, expect):
    """An argument matches its named envvar exactly, like an option does.

    And loses the distinction on Windows, like an option does.
    """

    @click.command()
    @click.argument("arg", envvar="ArG", required=False)
    def cmd(arg):
        click.echo(repr(arg))

    result = runner.invoke(cmd, [], env=env)
    assert not result.exception
    if ENV_NAMES_ARE_CASE_INSENSITIVE:
        expect = "'foo'"
    assert result.output == f"{expect}\n"


def test_bytes_args(runner, monkeypatch):
    @click.command()
    @click.argument("arg")
    def from_bytes(arg):
        assert isinstance(arg, str), (
            "UTF-8 encoded argument should be implicitly converted to Unicode"
        )

    # Simulate empty locale environment variables
    monkeypatch.setattr(sys, "getfilesystemencoding", lambda: "utf-8")
    monkeypatch.setattr(sys, "getdefaultencoding", lambda: "utf-8")
    # sys.stdin.encoding is readonly, needs some extra effort to patch.
    stdin = mock.Mock(wraps=sys.stdin)
    stdin.encoding = "utf-8"
    monkeypatch.setattr(sys, "stdin", stdin)

    runner.invoke(
        from_bytes,
        ["Something outside of ASCII range: 林".encode()],
        catch_exceptions=False,
    )


def test_file_args(runner, tmp_path):
    @click.command()
    @click.argument("input", type=click.File("rb"))
    @click.argument("output", type=click.File("wb"))
    def inout(input, output):
        while True:
            chunk = input.read(1024)
            if not chunk:
                break
            output.write(chunk)

    hello = tmp_path / "hello.txt"
    result = runner.invoke(inout, ["-", str(hello)], input="Hey!")
    assert result.output == ""
    assert result.exit_code == 0
    assert hello.read_bytes() == b"Hey!"

    result = runner.invoke(inout, [str(hello), "-"])
    assert result.output == "Hey!"
    assert result.exit_code == 0


def test_path_allow_dash(runner):
    @click.command()
    @click.argument("input", type=click.Path(allow_dash=True))
    def foo(input):
        click.echo(input)

    result = runner.invoke(foo, ["-"])
    assert result.output == "-\n"
    assert result.exit_code == 0


def test_file_atomics(runner, tmp_path):
    @click.command()
    @click.argument("output", type=click.File("wb", atomic=True))
    def inout(output):
        output.write(b"Foo bar baz\n")
        output.flush()
        with open(output.name, "rb") as f:
            old_content = f.read()
            assert old_content == b"OLD\n"

    foo = tmp_path / "foo.txt"
    foo.write_bytes(b"OLD\n")
    result = runner.invoke(inout, [str(foo)], input="Hey!", catch_exceptions=False)
    assert result.output == ""
    assert result.exit_code == 0
    assert foo.read_bytes() == b"Foo bar baz\n"


def test_stdout_default(runner):
    @click.command()
    @click.argument("output", type=click.File("w"), default="-")
    def inout(output):
        output.write("Foo bar baz\n")
        output.flush()

    result = runner.invoke(inout, [])
    assert not result.exception
    assert result.output == "Foo bar baz\n"
    assert result.stdout == "Foo bar baz\n"
    assert not result.stderr


@pytest.mark.parametrize(
    ("nargs", "value", "expect"),
    [
        (2, "", None),
        (2, "a", "Takes 2 values but 1 was given."),
        (2, "a b", ("a", "b")),
        (2, "a b c", "Takes 2 values but 3 were given."),
        (-1, "a b c", ("a", "b", "c")),
        (-1, "", ()),
    ],
)
def test_nargs_envvar(runner, nargs, value, expect):
    if nargs == -1:
        param = click.argument("arg", envvar="X", nargs=nargs)
    else:
        param = click.option("--arg", envvar="X", nargs=nargs)

    @click.command()
    @param
    def cmd(arg):
        return arg

    result = runner.invoke(cmd, env={"X": value}, standalone_mode=False)

    if isinstance(expect, str):
        assert isinstance(result.exception, click.BadParameter)
        assert expect in result.exception.format_message()
    else:
        assert result.return_value == expect


def test_nargs_envvar_only_if_values_empty(runner):
    @click.command()
    @click.argument("arg", envvar="X", nargs=-1)
    def cli(arg):
        return arg

